import { describe, it, expectTypeOf } from "vitest";
import type { ErrorInput, HTTPError } from "../../src/index.ts";
import {
  defineHandler,
  getQuery,
  readBody,
  readValidatedBody,
  getValidatedQuery,
  defineValidatedHandler,
  defineWebSocketHandler,
  defineLazyEventHandler,
  defineRoute,
  toEventHandler,
  withBase,
  requireBasicAuth,
} from "../../src/index.ts";
