  statusMessage?: string;

  /**
   * RFC 9457 `type`: URI that identifies the problem type.
   *
   * Only strings are accepted. It is not read from `cause`.
   */
  type?: string;

  /**
   * RFC 9457 `instance`: URI (or reference) of this problem occurrence.
   *
   * Only strings are accepted. It is not read from `cause`.
   */
