          "bar=38afes7a8; Domain=somecompany.co.uk; Path=/api; Expires=Wed, 30 Aug 2022 00:00:00 GMT",
        ]);
      });

      it("can remove cookie path", async () => {
        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            cookiePathRewrite: {
              "/": "",
            },
          });
        });

        const result = await t.fetch("/");

        expect(result.headers.getSetCookie()[0]).toEqual(
          "foo=219ffwef9w0f; Domain=somecompany.co.uk; Expires=Wed, 30 Aug 2022 00:00:00 GMT",
        );
      });
    });

    describe("onResponse", () => {
      beforeEach(() => {
        t.app.all("/debug", () => {
          return {
            foo: "bar",
          };
        });
      });

      it("allows modifying response event", async () => {
        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            onResponse(event) {
              event.res.headers.set("x-custom", "hello");
            },
          });
        });

        const result = await t.fetch("/");

        expect(result.headers.get("x-custom")).toEqual("hello");
      });

      it("allows modifying response event async", async () => {
        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            onResponse(_event) {
              return new Promise((resolve) => {
                resolve(event.res.headers.set("x-custom", "hello"));
              });
            },
          });
        });

        const result = await t.fetch("/");

        expect(result.headers.get("x-custom")).toEqual("hello");
      });

      it("allows to get the actual response", async () => {
        let headers;

        t.app.all("/", (event) => {
          return proxyRequest(event, "/debug", {
            onResponse(_event, response) {
              headers = Object.fromEntries(response.headers.entries());
            },
          });
        });

        await t.fetch("/");

        expect(headers?.["content-type"]).toEqual("application/json;charset=UTF-8");
      });
    });
  });
});

import { describe, it, expect } from "vitest";
import { defineRoute } from "../src/utils/route.ts";
import { H3 } from "../src/h3.ts";
import { z } from "zod";

describe("defineRoute", () => {
  it("should create a plugin that automatically registers the route", async () => {
    const app = new H3();
    const testRoute = defineRoute({
      method: "GET",
      route: "/test",
      handler: () => "test response",
    });
    app.register(testRoute);
    const res = await app.request("/test");
    expect(await res.text()).toBe("test response");
  });

  it("should support middleware", async () => {
    const app = new H3();
    const routePlugin = defineRoute({
      method: "POST",
      route: "/test",
      middleware: [
        (event) => {
          event.res.headers.set("X-Middleware", "works");
        },
      ],
      handler: () => "ok",
    });
    app.register(routePlugin);
    const res = await app.request("/test", { method: "POST" });
    expect(await res.text()).toBe("ok");
    expect(res.headers.get("X-Middleware")).toBe("works");
  });

  it("should register route with meta information", async () => {
    const app = new H3();
    const routePlugin = defineRoute({
      method: "GET",
      route: "/api/test",
      meta: { custom: "value" },
      handler: () => "ok",
    });
    app.register(routePlugin);

    // Check that route was registered
    const route = app["~routes"].find((r) => r.route === "/api/test" && r.method === "GET");

    expect(route).toMatchObject({
      route: "/api/test",
      method: "GET",
      meta: { custom: "value" },
      handler: expect.any(Function),
    });
  });

  it("should work with validation schemas", async () => {
    const app = new H3();
    const routePlugin = defineRoute({
      method: "POST",
      route: "/users",
      validate: {
        query: z.object({ id: z.string().uuid() }),
      },
      handler: () => "user created",
    });
    app.register(routePlugin);
    const res = await app.request("/users", { method: "POST" });
    expect(await res.json()).toMatchObject({
      status: 400,
      statusText: "Validation failed",
      data: { issues: [{ path: ["id"] }] },
    });
  });

  it("should use validate.onError for validation failures", async () => {
    const app = new H3();
    const routePlugin = defineRoute({
      method: "GET",
      route: "/users",
      validate: {
        query: z.object({ id: z.string().uuid() }),
        onError: (result) => ({ status: 422, message: `Invalid ${result._source}` }),
      },
      handler: () => "ok",
    });
    app.register(routePlugin);
    const res = await app.request("/users");
    expect(res.status).toBe(422);
    expect(await res.json()).toMatchObject({ message: "Invalid query" });
  });
});

